// vCard read in full (RFC 6350). test/oracle/vcard.json is generated by
// tools/oracle/vcard.py from the RFC and IANA's vCard Elements registry: the
// standard's whole inventory, and every example line the RFC gives (plus one
// derived from the RFC's own example for a registry value it shows nowhere).
// The page's reader (site/read/vcard.mjs, with its generated table) must read
// each line exactly as the reference reader does, and every registry entry
// must be implemented and exercised, or be listed in the shrinking debt of
// app/specs/oracle/vcard.json with a reason.
// usage: node --test test/oracle/vcard.test.mjs
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import test from "node:test";
import { readCard, readLine } from "../../site/read/vcard.mjs";
import { PROPERTIES, PARAMETERS } from "../../site/read/vcard.table.mjs";

const { inventory, examples } = JSON.parse(readFileSync("test/oracle/vcard.json", "utf8"));
const spec = JSON.parse(readFileSync("app/specs/oracle/vcard.json", "utf8"));
const { corpus } = JSON.parse(readFileSync("test/oracle/corpus.json", "utf8"));

test("the table and the examples are what the pinned RFC and registry give", () => {
  const run = spawnSync("python3", ["-I", "tools/oracle/vcard.py", "--check", "--cache", join(tmpdir(), "prism-oracle")], { encoding: "utf8" });
  assert.equal(run.status, 0, run.stderr || run.stdout);
});

test("every example line reads as RFC 6350 reads it", () => {
  const wrong = examples.filter((e) => JSON.stringify(readLine(e.raw)) !== JSON.stringify(e.expect));
  assert.deepEqual(wrong.map((e) => ({ id: e.id, got: readLine(e.raw) })), []);
});

test("every registry entry of RFC 6350 is implemented and exercised, or in debt with a reason", () => {
  const debt = new Set(spec.debt.map((d) => d.name));
  const unmet = inventory.filter((e) => !(e.implemented && e.examples.length) && !debt.has(`${e.kind} ${e.name}`));
  assert.deepEqual(unmet.map((e) => `${e.kind} ${e.name}`), []);
  for (const e of inventory.filter((e) => e.kind === "property")) assert.ok(PROPERTIES[e.name], `${e.name} is not in the page's table`);
  for (const e of inventory.filter((e) => e.kind === "parameter")) assert.ok(PARAMETERS[e.name], `${e.name} is not in the page's table`);
  assert.ok(inventory.filter((e) => e.kind === "property").length >= 35, "RFC 6350 defines at least 35 properties");
});

test("every whole vCard the RFC gives is read property by property", () => {
  const cards = corpus.filter((c) => c.source === "rfc6350");
  assert.ok(cards.length);
  for (const c of cards) {
    const card = readCard(c.raw);
    if (c.expect.title) assert.equal(card.FN?.[0]?.value, c.expect.title, c.id);
    assert.ok(!card.BEGIN && !card.END && !card.VERSION, c.id);
  }
});
